solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <sstream>
#include <string>
#include <vector>

struct Insn { std::size_t offset; std::size_t length; std::size_t variableAt; std::size_t variableLength; };

std::string toPattern(const std::vector<std::uint8_t>& code, const std::vector<Insn>& insns)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    std::string out;
    for (const Insn& in : insns)
    {
        for (std::size_t k{ 0 }; k < in.length; ++k)
        {
            if (!out.empty()) out += ' ';
            const bool variable{ in.variableLength && k >= in.variableAt && k < in.variableAt + in.variableLength };
            if (variable) out += "??";
            else { const std::uint8_t b{ code[in.offset + k] }; out += HEX[b >> 4]; out += HEX[b & 0xF]; }
        }
    }
    return out;
}

std::size_t countMatches(const std::vector<std::uint8_t>& code, const std::string& pattern)
{
    std::vector<int> bytes;
    std::istringstream in{ pattern };
    std::string token;
    while (in >> token) bytes.push_back(token == "??" ? -1 : static_cast<int>(std::stoul(token, nullptr, 16)));
    if (bytes.empty() || bytes.size() > code.size()) return 0;
    std::size_t n{ 0 };
    for (std::size_t i{ 0 }; i + bytes.size() <= code.size(); ++i)
    {
        bool match{ true };
        for (std::size_t k{ 0 }; k < bytes.size() && match; ++k) match = bytes[k] < 0 || code[i + k] == bytes[k];
        if (match) ++n;
    }
    return n;
}

std::optional<std::string> makeSignature(const std::vector<std::uint8_t>& code, const std::vector<Insn>& insns,
                                         std::size_t first, std::size_t maxBytes)
{
    std::vector<Insn> used;
    std::size_t size{ 0 };
    for (std::size_t i{ first }; i < insns.size(); ++i)
    {
        if (size + insns[i].length > maxBytes) return std::nullopt;
        used.push_back(insns[i]);
        size += insns[i].length;
        const std::string pattern{ toPattern(code, used) };
        if (countMatches(code, pattern) == 1) return pattern;
    }
    return std::nullopt;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
// sub eax, ebx / mov [rdi+1Ch], eax / mov rcx, [rip+disp] / call rel32, and the same first two instructions elsewhere
static Bytes code()
{
    return { 0x2B, 0xC3, 0x89, 0x47, 0x1C, 0x48, 0x8B, 0x0D, 0x6A, 0x2F, 0x01, 0x00, 0xE8, 0xF5, 0x03, 0x00, 0x00, 0xC3,
             0x2B, 0xC3, 0x89, 0x47, 0x1C, 0x48, 0x8B, 0x0D, 0x11, 0x22, 0x33, 0x44, 0x90, 0xC3 };
}
static std::vector<Insn> insns()
{
    return { { 0, 2, 0, 0 }, { 2, 3, 0, 0 }, { 5, 7, 3, 4 }, { 12, 5, 1, 4 }, { 17, 1, 0, 0 } };
}

TEST("patterns with wildcards") {
    CHECK_EQ(toPattern(code(), { insns()[0], insns()[1] }), std::string("2B C3 89 47 1C"));
    CHECK_EQ(toPattern(code(), { insns()[2] }), std::string("48 8B 0D ?? ?? ?? ??"));
    CHECK_EQ(toPattern(code(), { insns()[3] }), std::string("E8 ?? ?? ?? ??"));
}
TEST("counting matches") {
    CHECK_EQ(countMatches(code(), "2B C3 89 47 1C"), 2u);
    CHECK_EQ(countMatches(code(), "48 8B 0D ?? ?? ?? ??"), 2u);
    CHECK_EQ(countMatches(code(), "C3"), 4u);
    CHECK_EQ(countMatches(code(), "90 C3"), 1u);
    CHECK_EQ(countMatches(code(), "FF"), 0u);
}
TEST("growing until unique") {
    const auto sig{ makeSignature(code(), insns(), 0, 32) };
    CHECK(sig.has_value());
    if (sig) CHECK_EQ(*sig, std::string("2B C3 89 47 1C 48 8B 0D ?? ?? ?? ?? E8 ?? ?? ?? ??"));
    const auto fromCall{ makeSignature(code(), insns(), 3, 32) };
    if (fromCall) CHECK_EQ(*fromCall, std::string("E8 ?? ?? ?? ??"));
    CHECK(fromCall.has_value());
}
TEST("limits") {
    CHECK(!makeSignature(code(), insns(), 0, 12).has_value());
    CHECK(!makeSignature(code(), { insns()[0], insns()[1] }, 0, 32).has_value());
}

